  'retention.noAccountBody': '“{name}” ಎಂಬ ಖಾತೆ ಇಲ್ಲ.',
  'retention.holdTitle': '{email} ಅನ್ನು ಕಾನೂನು ತಡೆಯಲ್ಲಿ ಇರಿಸಬೇಕೇ?',
  'retention.holdBody': 'ಈ ಖಾತೆಯಲ್ಲಿರುವ ಏನನ್ನೂ ಶಾಶ್ವತವಾಗಿ ಅಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ: ಅದರ ಮಾಲೀಕರಿಂದಲೂ ಅಲ್ಲ, ಉಳಿಸಿಕೊಳ್ಳುವ ನಿಯಮಗಳಿಂದಲೂ ಅಲ್ಲ, ಮತ್ತು ಖಾತೆಯನ್ನೇ ಅಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಅವರು ಈಗಲೂ ಮೇಲ್ ಓದಬಹುದು, ಕಳುಹಿಸಬಹುದು ಮತ್ತು ಸರಿಸಬಹುದು.',
  'retention.putOnHold': 'ತಡೆಯಲ್ಲಿ ಇರಿಸಿ',
  'retention.ownTitle': '{email} ಗಾಗಿ ಮೇಲ್ ವಯಸ್ಸಿನ ಮಿತಿ',
  'retention.ownBody': 'ಈ ಖಾತೆಯ ಇಷ್ಟು ವರ್ಷಗಳಿಗಿಂತ ಹಳೆಯ ಮೇಲ್ ಅಳಿಸಿ. 0 ಎಂದರೆ ಶಾಶ್ವತವಾಗಿ ಇರಿಸುವುದು. ಸರ್ವರ್ ನಿಯಮವನ್ನು ಅನುಸರಿಸಲು ಖಾಲಿ ಬಿಡಿ.',
  'retention.yearsLabel': 'ವರ್ಷಗಳು',
  'retention.daysLabel': 'ದಿನಗಳು',
  'retention.next': 'ಮುಂದೆ',
  'retention.ownConfirmTitle': '{email} ಅವರ {age} ಗಿಂತ ಹಳೆಯ ಮೇಲ್ ಅಳಿಸಬೇಕೇ?',
  'retention.ownConfirmBody': 'ಇದು ಈಗ ನಡೆದರೆ: {summary} ಅಳಿಸಿದ ಮೇಲ್ ಅನ್ನು ಮರಳಿ ತರಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'retention.nothingToDelete': 'ಅಳಿಸಲು ಏನೂ ಇಲ್ಲ',
  'retention.nothingToDeleteBody': 'ಸದ್ಯಕ್ಕೆ ಯಾವ ಮೇಲ್ ಸಹ ಅದರ ಮಿತಿಯನ್ನು ಮೀರಿಲ್ಲ.',
  'retention.runTitle': 'ಈಗಲೇ ಸ್ವಚ್ಛತೆ ನಡೆಸಬೇಕೇ?',
  // context: {summary} is retention.summary, e.g. "12 messages in 3 accounts (a@x.com, …)."
  'retention.runBody': 'ಇದು ಅಳಿಸುತ್ತದೆ: {summary} ಅಳಿಸಿದ ಮೇಲ್ ಅನ್ನು ಮರಳಿ ತರಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'retention.deleteNow': 'ಈಗಲೇ ಅಳಿಸಿ',
  'retention.doneTitle': 'ಸ್ವಚ್ಛತೆ ಮುಗಿದಿದೆ',
  'retention.doneBody': { one: '{count} ಸಂದೇಶವನ್ನು ಅಳಿಸಲಾಗಿದೆ.', other: '{count} ಸಂದೇಶಗಳನ್ನು ಅಳಿಸಲಾಗಿದೆ.' },
  'retention.serverNote': 'ಮೇಲ್ ಸರ್ವರ್ ಇಷ್ಟು ದಿನಗಳ ನಂತರ ಪ್ರತಿ ಖಾತೆಯ ಅನುಪಯುಕ್ತ ಮತ್ತು ಸ್ಪ್ಯಾಮ್ ಅನ್ನು ಖಾಲಿ ಮಾಡುತ್ತದೆ. ಜನರು ತಮ್ಮ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಕಡಿಮೆ ಸಮಯವನ್ನು ಆರಿಸಬಹುದು.',
  'retention.heldBanner': { one: 'ಒಂದು ಖಾತೆ ಕಾನೂನು ತಡೆಯಲ್ಲಿದೆ, ಆದರೆ ಮೇಲ್ ಸರ್ವರ್ {count} ದಿನದ ನಂತರ ಅದರ ಅನುಪಯುಕ್ತ ಮತ್ತು ಸ್ಪ್ಯಾಮ್ ಅನ್ನು ಖಾಲಿ ಮಾಡುತ್ತದೆ (ಇದನ್ನು ಪ್ರತಿ ಖಾತೆಗೆ ಪ್ರತ್ಯೇಕವಾಗಿ ಹೊಂದಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ). ತಡೆ ಇರುವವರೆಗೆ ಅವುಗಳನ್ನು ಉಳಿಸಲು ದಿನಗಳನ್ನು 0 ಗೆ ಹೊಂದಿಸಿ.', other: 'ಒಂದು ಖಾತೆ ಕಾನೂನು ತಡೆಯಲ್ಲಿದೆ, ಆದರೆ ಮೇಲ್ ಸರ್ವರ್ {count} ದಿನಗಳ ನಂತರ ಅದರ ಅನುಪಯುಕ್ತ ಮತ್ತು ಸ್ಪ್ಯಾಮ್ ಅನ್ನು ಖಾಲಿ ಮಾಡುತ್ತದೆ (ಇದನ್ನು ಪ್ರತಿ ಖಾತೆಗೆ ಪ್ರತ್ಯೇಕವಾಗಿ ಹೊಂದಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ). ತಡೆ ಇರುವವರೆಗೆ ಅವುಗಳನ್ನು ಉಳಿಸಲು ದಿನಗಳನ್ನು 0 ಗೆ ಹೊಂದಿಸಿ.' },
  'retention.deleteOld': 'ಹಳೆಯ ಮೇಲ್ ಅಳಿಸಿ',
  'retention.deleteOldNote': 'ಇದಕ್ಕಿಂತ ಹಳೆಯ ಮೇಲ್ ಅನ್ನು ಪ್ರತಿ ಖಾತೆಯಲ್ಲೂ ಪ್ರತಿ ರಾತ್ರಿ ಅಳಿಸಿ. 0 ಎಂದರೆ ಮೇಲ್ ಅನ್ನು ಶಾಶ್ವತವಾಗಿ ಇರಿಸುವುದು. ಏನನ್ನಾದರೂ ಉಳಿಸುವ ಮೊದಲು ಎಷ್ಟು ಹೋಗುತ್ತದೆ ಎಂದು ನೀವು ನೋಡುತ್ತೀರಿ.',
  'retention.runNow': 'ಈಗಲೇ ಸ್ವಚ್ಛತೆ ನಡೆಸಿ',
  'retention.accounts': 'ಖಾತೆಗಳು',
  'retention.accountsNote': 'ಒಂದು ಖಾತೆಗೆ ಅದರದೇ ಮಿತಿ ನೀಡಿ, ಅಥವಾ ಅದನ್ನು ಕಾನೂನು ತಡೆಯಲ್ಲಿ ಇರಿಸಿ: ನೀವು ಬಿಡುಗಡೆ ಮಾಡುವವರೆಗೆ ಅದರಲ್ಲಿರುವ ಏನನ್ನೂ ಯಾರೂ ಶಾಶ್ವತವಾಗಿ ಅಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'retention.accountPlaceholder': 'ಬಳಕೆದಾರಹೆಸರು ಅಥವಾ ಪೂರ್ಣ ವಿಳಾಸ',
