  // Masked addresses
  'addresses.title': 'ಮುಖವಾಡದ ವಿಳಾಸಗಳು',
  'addresses.intro': 'ಪ್ರತಿ ಅಂಗಡಿ, ಆ್ಯಪ್ ಅಥವಾ ಸುದ್ದಿಪತ್ರಕ್ಕೆ ಬೇರೆ ಬೇರೆ ವಿಳಾಸ ನೀಡಿ. ಮೇಲ್ ಎಂದಿನಂತೆ ಇಲ್ಲಿಗೆ ಬರುತ್ತದೆ. ಯಾವುದಾದರೂ ಒಂದಕ್ಕೆ ಸ್ಪ್ಯಾಮ್ ಬರಲು ಶುರುವಾದರೆ ಅಥವಾ ಅದು ಮಾರಾಟವಾದರೆ, ಅದನ್ನು ಆಫ್ ಮಾಡಿ.',
