  'addresses.deleteBody': 'ಇದಕ್ಕೆ ಕಳುಹಿಸಿದ ಮೇಲ್ ಹಿಂತಿರುಗುತ್ತದೆ, ಮತ್ತು ಇದನ್ನು ಮರಳಿ ತರಲು ಸಾಧ್ಯವಿಲ್ಲ. ಬದಲಿಗೆ ವಿರಾಮಗೊಳಿಸಲು, ಇದನ್ನು ಆಫ್ ಮಾಡಿ.',
