  // Shared files
  'sharedfiles.title': 'ಹಂಚಿಕೊಂಡ ಫೈಲ್‌ಗಳು',
  'sharedfiles.intro': 'ಲಗತ್ತಿಸಲು ತುಂಬಾ ದೊಡ್ಡದಾದ ಫೈಲ್‌ಗಳು, ಡೌನ್‌ಲೋಡ್ ಲಿಂಕ್‌ಗಳಾಗಿ ಕಳುಹಿಸಲಾಗಿದೆ. ಲಿಂಕ್‌ನ ಅವಧಿ ಮುಗಿಯುವವರೆಗೆ ಅಥವಾ ನೀವು ತೆಗೆದುಹಾಕುವವರೆಗೆ ಅವು ನಿಮ್ಮ ಸಂಗ್ರಹಣೆಯನ್ನು ಬಳಸುತ್ತವೆ.',
