  'encryption.noEmail': 'ಆ ಕೀಯಲ್ಲಿ ಯಾವುದೇ ಇಮೇಲ್ ವಿಳಾಸವಿಲ್ಲ.',
  'encryption.notAKey': 'ಅದು OpenPGP ಸಾರ್ವಜನಿಕ ಕೀಯಂತೆ ಕಾಣುತ್ತಿಲ್ಲ.',
  'encryption.peopleKeys': 'ಜನರ ಕೀಗಳು',
