  'encryption.conflict': '{source} ಬೇರೊಂದು ಕೀ ಬಂದಿದೆ: {fp}. ಯಾರೋ {email} ಎಂದು ನಟಿಸುತ್ತಿರಬಹುದು. ನೀವು ಆಯ್ಕೆ ಮಾಡುವವರೆಗೆ ಅವರಿಗೆ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿದ ಮೇಲ್ ವಿರಾಮಗೊಂಡಿದೆ. ಬೇರೆ ಮಾರ್ಗದಲ್ಲಿ ಅವರೊಂದಿಗೆ ಪರಿಶೀಲಿಸಿ.',
