  'encryption.pastePlaceholder': 'ಯಾರದಾದರೂ ಸಾರ್ವಜನಿಕ ಕೀ ಅಂಟಿಸಿ (-----BEGIN PGP PUBLIC KEY BLOCK-----…)',
