  'encryption.couldntOpen': 'ತೆರೆಯಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ: {error}',
  'encryption.verifiedEncrypted': 'ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿದೆ · ಪರಿಶೀಲಿಸಲಾಗಿದೆ: {who} ಅವರ ಕೀಯಿಂದ ಸಹಿ ಮಾಡಲಾಗಿದೆ. ಹುಡುಕಾಟ ಇದರ ಒಳಗೆ ನೋಡಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'encryption.verifiedSigned': 'ಸಹಿ ಮಾಡಲಾಗಿದೆ · ಪರಿಶೀಲಿಸಲಾಗಿದೆ: {who} ಅವರ ಕೀಯಿಂದ ಸಹಿ ಮಾಡಲಾಗಿದೆ.',
  'encryption.badSignature': 'ಸಹಿ ಹೊಂದುತ್ತಿಲ್ಲ. ಈ ಸಂದೇಶವನ್ನು ದಾರಿಯಲ್ಲಿ ಬದಲಾಯಿಸಲಾಗಿದೆ, ಅಥವಾ ಇದು ನಿಜವಾಗಿಯೂ {who} ಅವರಿಂದ ಬಂದಿಲ್ಲ. ಇದು ಮಾಡಲು ಹೇಳುವುದನ್ನು ನಂಬಬೇಡಿ.',
  'encryption.unverifiedEncrypted': 'ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿದೆ · ಸಹಿ ಪರಿಶೀಲಿಸಲಾಗಿಲ್ಲ: ಅದನ್ನು ಪರಿಶೀಲಿಸಲು ನಮ್ಮ ಬಳಿ {who} ಅವರ ಕೀ ಇಲ್ಲ, ಆದ್ದರಿಂದ ಇದನ್ನು ಯಾರು ಬರೆದರು ಎಂದು ಹೇಳಲು ಸಾಧ್ಯವಿಲ್ಲ. ಹುಡುಕಾಟ ಇದರ ಒಳಗೆ ನೋಡಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'encryption.unverifiedSigned': 'ಸಹಿ ಪರಿಶೀಲಿಸಲಾಗಿಲ್ಲ: ಅದನ್ನು ಪರಿಶೀಲಿಸಲು ನಮ್ಮ ಬಳಿ {who} ಅವರ ಕೀ ಇಲ್ಲ, ಆದ್ದರಿಂದ ಇದನ್ನು ಯಾರು ಬರೆದರು ಎಂದು ಹೇಳಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'encryption.notSigned': 'ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿದೆ · ಸಹಿ ಮಾಡಿಲ್ಲ. ಹುಡುಕಾಟ ಇದರ ಒಳಗೆ ನೋಡಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'encryption.keyChanged': '{who} ಅವರ ಕೀ ಬದಲಾಗಿದೆ. ಇದು ಹೊಸ ಸಾಧನವಾಗಿರಬಹುದು, ಅಥವಾ ಯಾರೋ ಅವರಂತೆ ನಟಿಸುತ್ತಿರಬಹುದು. ಅವರಿಗೆ ಖಾಸಗಿ ಏನನ್ನಾದರೂ ಕಳುಹಿಸುವ ಮೊದಲು ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಭದ್ರತೆ ಇಲ್ಲಿ ಪರಿಶೀಲಿಸಿ.',
  'encryption.smime': 'ಈ ಸಂದೇಶವನ್ನು S/MIME ಮೂಲಕ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗಿದೆ. ನಿಮ್ಮ ಪ್ರಮಾಣಪತ್ರ ಇರುವ ಮೇಲ್ ಆ್ಯಪ್‌ನಲ್ಲಿ (Apple Mail, Outlook ಅಥವಾ Thunderbird) ಇದನ್ನು ತೆರೆಯಿರಿ.',
  'encryption.decrypting': 'ಈ ಸಾಧನದಲ್ಲಿ ಡೀಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗುತ್ತಿದೆ…',
  'encryption.locked': 'ಈ ಸಂದೇಶ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿದೆ. ಇಲ್ಲಿ ಓದಲು ನಿಮ್ಮ ಕೀ ಅನ್‌ಲಾಕ್ ಮಾಡಿ.',
  'encryption.noKeyHere': 'ಈ ಸಂದೇಶವನ್ನು ನಿಮ್ಮ ಕೀಗೆ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗಿದೆ, ಅದು ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿಲ್ಲ. ಇಲ್ಲಿ ಓದಲು ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಭದ್ರತೆ ಇಲ್ಲಿ ನಿಮ್ಮ ಕೀ ಬ್ಯಾಕಪ್ ಮರುಸ್ಥಾಪಿಸಿ.',
  'encryption.attachments': 'ಲಗತ್ತುಗಳು',
