  // {time}: a time of day, e.g. "3:45 PM"
  'oauth.blockedUntil': 'ನಿಮ್ಮ ನೆಟ್‌ವರ್ಕ್‌ನಿಂದ ತುಂಬಾ ಸೈನ್ ಇನ್‌ಗಳು ವಿಫಲವಾಗಿವೆ, ಆದ್ದರಿಂದ ಅದನ್ನು ಸ್ವಲ್ಪ ಸಮಯ ನಿರ್ಬಂಧಿಸಲಾಗಿದೆ. ಇದು ತಾತ್ಕಾಲಿಕ: {time} ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ. ನಿಮ್ಮ ಪಾಸ್‌ವರ್ಡ್ ಮರೆತಿದ್ದರೆ, ಅದನ್ನು ಮರುಹೊಂದಿಸಲು ನಿಮ್ಮ ನಿರ್ವಾಹಕರನ್ನು ಕೇಳಿ.',
  'oauth.blocked': 'ನಿಮ್ಮ ನೆಟ್‌ವರ್ಕ್‌ನಿಂದ ತುಂಬಾ ಸೈನ್ ಇನ್‌ಗಳು ವಿಫಲವಾಗಿವೆ, ಆದ್ದರಿಂದ ಅದನ್ನು ಸ್ವಲ್ಪ ಸಮಯ ನಿರ್ಬಂಧಿಸಲಾಗಿದೆ. ಇದು ತಾತ್ಕಾಲಿಕ, ಸಾಮಾನ್ಯವಾಗಿ ಸುಮಾರು ಒಂದು ಗಂಟೆ. ನಿಮ್ಮ ಪಾಸ್‌ವರ್ಡ್ ಮರೆತಿದ್ದರೆ, ಅದನ್ನು ಮರುಹೊಂದಿಸಲು ನಿಮ್ಮ ನಿರ್ವಾಹಕರನ್ನು ಕೇಳಿ.',
  'oauth.failed': 'ಸೈನ್ ಇನ್ ವಿಫಲವಾಗಿದೆ ({status})',
  'oauth.ssoExpired': 'ಆ ಸೈನ್ ಇನ್‌ಗೆ ತುಂಬಾ ಸಮಯ ಹಿಡಿಯಿತು ಅಥವಾ ಅದನ್ನು ಈಗಾಗಲೇ ಬಳಸಲಾಗಿದೆ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
  'oauth.ssoCancelled': 'ಸೈನ್ ಇನ್ ರದ್ದುಮಾಡಲಾಗಿದೆ.',
  'oauth.ssoRefused': 'ನಿಮ್ಮ ಸೈನ್ ಇನ್ ಅನ್ನು ಪರಿಶೀಲಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ, ಅಥವಾ ನಿಮ್ಮ ನಿರ್ವಾಹಕರನ್ನು ಕೇಳಿ.',
  'oauth.ssoNoAccount': 'ಆ ಖಾತೆ ಈ ಮೇಲ್ ಸರ್ವರ್ ಬಳಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ನಿಮ್ಮ ಕೆಲಸದ ವಿಳಾಸದಿಂದ ಸೈನ್ ಇನ್ ಮಾಡಿ, ಅಥವಾ ನಿಮ್ಮ ನಿರ್ವಾಹಕರನ್ನು ಕೇಳಿ.',
