  'admin.disableBody': 'ಅವರು ಎಲ್ಲೆಡೆಯಿಂದ ಸೈನ್ ಔಟ್ ಆಗುತ್ತಾರೆ ಮತ್ತು ನೀವು ಖಾತೆಯನ್ನು ಮತ್ತೆ ಸಕ್ರಿಯಗೊಳಿಸುವವರೆಗೆ ಸೈನ್ ಇನ್ ಮಾಡಲು ಅಥವಾ ಕಳುಹಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಅವರಿಗೆ ಕಳುಹಿಸಿದ ಮೇಲ್ ಈಗಲೂ ಬರುತ್ತದೆ.',
