  'admin.suspendTitle': '{email} ಗಾಗಿ ಕಳುಹಿಸುವಿಕೆ ಅಮಾನತುಗೊಳಿಸಬೇಕೇ?',
  'admin.suspendBody': 'ಅವರು ಈಗಲೂ ಸೈನ್ ಇನ್ ಮಾಡಿ ತಮ್ಮ ಮೇಲ್ ಓದಬಹುದು, ಆದರೆ ನೀವು ಮತ್ತೆ ಅನುಮತಿಸುವವರೆಗೆ ಕಳುಹಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ನಿರ್ವಾಹಕರು ಇದನ್ನು ಮಾಡಿದ್ದಾರೆ ಎಂಬ ಸೂಚನೆಯನ್ನು ಅವರು ನೋಡುತ್ತಾರೆ.',
