  'admin.deleteLabel': '{email} ಅಳಿಸಿ',
  'admin.deleteTitle': '{email} ಅಳಿಸಬೇಕೇ?',
  'admin.deleteUserBody': 'ಅದರ ಎಲ್ಲಾ ಮೇಲ್, ಸಂಪರ್ಕಗಳು, ಕ್ಯಾಲೆಂಡರ್‌ಗಳು ಮತ್ತು ಫೈಲ್‌ಗಳನ್ನು ಅಳಿಸಲಾಗುತ್ತದೆ. ವಿಳಾಸವನ್ನು ನಿವೃತ್ತಿಗೊಳಿಸಲಾಗುತ್ತದೆ: ನಂತರ ಯಾರೂ ಅದನ್ನು ಪಡೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ. ಇದನ್ನು ರದ್ದುಗೊಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಯಾರಾದರೂ ಇದನ್ನು ಬಳಸುವುದನ್ನು ತಡೆಯಲು, ಬದಲಿಗೆ ಇದನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ.',
  'admin.deleteAccount': 'ಖಾತೆ ಅಳಿಸಿ',
  'admin.blockedHelp': 'ಪದೇ ಪದೇ ವಿಫಲ ಸೈನ್ ಇನ್‌ಗಳು ಅಥವಾ ತನಿಖೆಯ ನಂತರ ಮೇಲ್ ಸರ್ವರ್ ತಾನಾಗಿಯೇ ವಿಳಾಸವನ್ನು ನಿರ್ಬಂಧಿಸುತ್ತದೆ. ನಿಜವಾದ ವ್ಯಕ್ತಿ ಸಿಕ್ಕಿಹಾಕಿಕೊಂಡಾಗ ಅದನ್ನು ಅನಿರ್ಬಂಧಿಸಿ.',
  'admin.noBlocked': 'ಯಾವುದೇ ವಿಳಾಸಗಳನ್ನು ನಿರ್ಬಂಧಿಸಲಾಗಿಲ್ಲ.',
  'admin.untilUnblocked': 'ಅನಿರ್ಬಂಧಿಸುವವರೆಗೆ',
  'admin.unblock': 'ಅನಿರ್ಬಂಧಿಸಿ',
  'admin.newLimitsHelp': 'ಈ ಪಟ್ಟಿಯಲ್ಲಿರುವ ಖಾತೆಗಳು ಹೊಸ ಖಾತೆಗಳಿಗಾಗಿನ ಕಠಿಣ ಮಿತಿಯಲ್ಲಿ ಕಳುಹಿಸುತ್ತವೆ. ಖಾತೆ ವಿಶ್ವಾಸ ಗಳಿಸಿದ ನಂತರ ಅದನ್ನು ತೆಗೆಯಿರಿ; ಅದು ತುಂಬಾ ಕಳುಹಿಸಲು ಶುರುಮಾಡಿದರೆ ಮತ್ತೆ ಸೇರಿಸಿ.',
  'admin.newLimitsPlaceholder': 'ಬಳಕೆದಾರಹೆಸರು ಅಥವಾ ಪೂರ್ಣ ವಿಳಾಸ',
  'admin.newLimitsLabel': 'ಹೊಸ-ಖಾತೆ ಮಿತಿಗಳಲ್ಲಿ ಇರಿಸಬೇಕಾದ ಖಾತೆ',
