  'admin.domainsHelp': 'ಜನರು ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ನಿಮ್ಮ ಡೊಮೇನ್ ಇಲ್ಲಿ ಸೇರಿಸಿದ ಡೊಮೇನ್‌ಗಳು. ಪ್ರತಿಯೊಂದೂ ಒಂದು ಖಾತೆಗೆ ಸೇರಿದೆ. ಅದರ ಮಾಲೀಕತ್ವದ ದಾಖಲೆಯನ್ನು ಪ್ರತಿ ಕೆಲವು ಗಂಟೆಗಳಿಗೊಮ್ಮೆ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ; ಅದು ಇಲ್ಲದೆ 7 ದಿನಗಳಾದರೆ, ಡೊಮೇನ್‌ನ ವಿಳಾಸಗಳು ವಿರಾಮಗೊಳ್ಳುತ್ತವೆ.',
